import jdk.incubator.concurrent.ScopedValue;
import java.util.concurrent.StructuredTaskScope;

public class ScopedValueDemo {
    private static final ScopedValue<String> CURRENT_USER = ScopedValue.newInstance();

    public void handleRequest(String username) throws Exception {
        ScopedValue.where(CURRENT_USER, username).run(() -> {
            processSubTask();
        });
    }

    private void processSubTask() {
        // Read the immutable scoped value safely without explicit parameters
        System.out.println("Processing request for user: " + CURRENT_USER.get());
    }
}
